#include <bits/stdc++.h>
using namespace std;

// Returns the list of operations (1-indexed) to transform str1 into str2
// using the strategy: pair mismatches of the same type; if both odd, add two extra ops.
// Returns empty vector if impossible (different parity).
vector<pair<long long, long long>> minSwapsToBalance(const string& str1, const string& str2) {
    long long n = str1.size();
    vector<long long> s;  // positions where str1[i]=='a' and str2[i]=='b'
    vector<long long> t;  // positions where str1[i]=='b' and str2[i]=='a'
    for (long long i = 0; i < n; ++i) {
        if (str1[i] == 'a' && str2[i] == 'b') s.push_back(i);
        if (str1[i] == 'b' && str2[i] == 'a') t.push_back(i);
    }
    long long len1 = s.size(), len2 = t.size();
    if ((len1 % 2) != (len2 % 2)) {
        return {};  // impossible
    }
    vector<pair<long long, long long>> vec;
    // Pair even numbers from s
    for (long long i = 0; i + 1 < len1; i += 2) {
        vec.emplace_back(s[i] + 1, s[i + 1] + 1);
    }
    // Pair even numbers from t
    for (long long i = 0; i + 1 < len2; i += 2) {
        vec.emplace_back(t[i] + 1, t[i + 1] + 1);
    }
    // If both odd, handle the leftover pair
    if (len1 % 2 == 1 && len2 % 2 == 1) {
        long long a = s[len1 - 1];
        long long b = t[len2 - 1];
        vec.emplace_back(a + 1, a + 1);
        vec.emplace_back(a + 1, b + 1);
    }
    return vec;
}

