int main() {
    // Test 1: no mismatches
    {
        auto res = minSwapsToBalance("ab", "ab");
        assert(res.empty());
    }
    // Test 2: two type A mismatches
    {
        // str1="aa", str2="bb" -> s={0,1}, t={} -> one pair (1,2)
        auto res = minSwapsToBalance("aa", "bb");
        assert(res.size() == 1);
        assert(res[0].first == 1 && res[0].second == 2);
    }
    // Test 3: two type B mismatches
    {
        // str1="bb", str2="aa" -> t={0,1}, s={} -> one pair (1,2)
        auto res = minSwapsToBalance("bb", "aa");
        assert(res.size() == 1);
        assert(res[0].first == 1 && res[0].second == 2);
    }
    // Test 4: one of each -> odd, odd -> two extra ops
    {
        // str1="ab", str2="ba" -> s={0}, t={1}
        auto res = minSwapsToBalance("ab", "ba");
        assert(res.size() == 2);
        assert(res[0] == make_pair(1LL, 1LL));
        assert(res[1] == make_pair(1LL, 2LL));
    }
    // Test 5: impossible (different parity)
    {
        // str1="a", str2="b" -> s={0}, t={} -> len1 odd, len2 even
        auto res = minSwapsToBalance("a", "b");
        assert(res.empty());
    }
    // Test 6: mixed larger
    {
        // str1="abab", str2="baba" -> s: indices where (a,b) -> index0? str1[0]='a',str2[0]='b' -> s has 0
        // index1: str1[1]='b',str2[1]='a' -> t has 1
        // index2: str1[2]='a',str2[2]='b' -> s has 2
        // index3: str1[3]='b',str2[3]='a' -> t has 3
        // s={0,2}, t={1,3} -> both even -> two pairs: (1,3) and (2,4)
        auto res = minSwapsToBalance("abab", "baba");
        assert(res.size() == 2);
        assert(res[0] == make_pair(1LL, 3LL));
        assert(res[1] == make_pair(2LL, 4LL));
    }
    // Test 7: no mismatches with length 5
    {
        auto res = minSwapsToBalance("ababa", "ababa");
        assert(res.empty());
    }
    return 0;
}
